Implementar función `handleSubmit` con flujo completo:

```tsx
async function handleSubmit(data: FormData) {
  setIsSubmitting(true);
  setError(null);

  try {
    let referenceImageKey: string | undefined;

    // Paso 1: Si hay foto, obtener uploadUrl
    if (selectedFile) {
      const uploadRes = await fetch('/api/custom-requests', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ hasReference: true, mimeType: selectedFile.type })
      });

      if (!uploadRes.ok) throw new Error('Error al preparar subida');
      const { uploadUrl, key } = await uploadRes.json();

      // Paso 2: Subir foto a R2 con presigned URL
      const uploadToR2 = await fetch(uploadUrl, {
        method: 'PUT',
        body: selectedFile,
        headers: { 'Content-Type': selectedFile.type }
      });

      if (!uploadToR2.ok) throw new Error('Error al subir imagen');
      referenceImageKey = key;
    }

    // Paso 3: Enviar formulario completo
    const submitRes = await fetch('/api/custom-requests', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        ...data,
        turnstileToken,
        referenceImageKey
      })
    });

    if (!submitRes.ok) {
      const err = await submitRes.json();
      throw new Error(err.message || 'Error al enviar solicitud');
    }

    setIsSuccess(true);
  } catch (err) {
    setError(err.message);
    turnstileRef.current?.reset();
  } finally {
    setIsSubmitting(false);
  }
}
```

Estados de UI:
- `isSubmitting`: spinner y deshabilitar formulario
- `error`: mensaje de error con opción de reintentar
- `isSuccess`: ocultar formulario, mostrar mensaje de éxito
